from pathlib import Path
import re,json
W=Path(__file__).resolve().parent
D=W/'sources/review-p118-p134'
base=json.loads((D/'commentary-baseline.json').read_text())['comments']
revisions={}
revisions['p118']=base['p118'].replace('Die Umwandlung kann nach internationaler Löschung unter den bezeichneten protokollrechtlichen Voraussetzungen den bisherigen Rang für eine deutsche Anmeldung retten.','Die Umwandlung kann bei der in Absatz 1 bezeichneten Löschung nach Artikel 6 Absatz 4 des Madrider Protokolls den bisherigen Rang für eine deutsche Anmeldung retten. Nicht jede freiwillige Aufgabe einer internationalen Registrierung eröffnet diesen besonderen Fortsetzungsweg.').replace('Absatz 1 verlangt Eingang des Antrags mit den erforderlichen Angaben binnen drei Monaten nach Löschung.','Absatz 1 verlangt Eingang des Antrags mit den erforderlichen Angaben beim DPMA binnen drei Monaten nach dem Tag der Löschung im internationalen Register. Der spätere Zugang einer WIPO-Mitteilung ist nicht der hier bezeichnete Fristauslöser.').replace('Eine bloße Absichtserklärung zur späteren Neuanmeldung wahrt die Dreimonatsfrist nicht.','Eine bloße Absichtserklärung zur späteren Neuanmeldung wahrt die Dreimonatsfrist nicht. Das Registrierungsdatum und das Datum einer erst nachträglichen Erstreckung auf Deutschland sind auseinanderzuhalten; der frühere internationale Tag steht nicht beliebig für jeden später hinzugekommenen Schutzstaat zur Wahl.')
revisions['p119']=base['p119'].replace('§ 119 bildet mehrere genau begrenzte Brücken zur Unionsmarke.','§ 119 bildet mehrere genau begrenzte Brücken zur Unionsmarke. Die Nummern 1 und 2 ordnen unmittelbare, die Nummern 3 bis 6 entsprechende Anwendung an; diese bewusste Unterscheidung bestimmt die erforderlichen Anpassungen.').replace('Nummer 2 ergänzt die unionsrechtlichen Ansprüche um die aufgeführten deutschen Schadensersatz- und Durchsetzungsfolgen.','Nummer 2 ergänzt die unionsrechtlichen Ansprüche um Schadensersatz einschließlich der Zurechnung nach § 14 Absatz 7, Vernichtung und Rückruf, Auskunft, Vorlage und Besichtigung, Sicherung des Schadensersatzes und Urteilsbekanntmachung. Diese Instrumente behalten ihre jeweiligen Voraussetzungen; ein Verletzungsbefund gewährt nicht unterschiedslos jede Maßnahme.').replace('Nummern 4 und 5 passen Nichtbenutzungseinreden im Widerspruch und Nichtigkeitsverfahren an die unionsrechtliche Benutzung an; Nummer 5 übernimmt zudem die genannte Duldungsregel.','Nummer 4 betrifft den Widerspruch gegen eine deutsche Eintragung aus einer älteren eingetragenen Unionsmarke und verweist auf § 43 Absatz 1 mit Benutzung nach Artikel 18 der Verordnung. Nummer 5 erfasst die bezeichneten Antrags- und Klageverfahren: Buchstabe a übernimmt § 51 Absatz 2 Satz 1, Buchstabe b die Einreden und Nachweise aus § 53 Absatz 6 und § 55 Absatz 3 mit derselben unionsrechtlichen Benutzungsanknüpfung. Der Wortlaut zum Verfalls- und Nichtigkeitsverfahren erzeugt dabei keinen selbständigen Verfallsgrund aus bloßer Zeichenähnlichkeit; der konkrete Angriffsgrund bleibt gesondert nachzuweisen.')
revisions['p120']=base['p120'].replace('Bei Nichtbenutzungsverfall müssen sie jedoch bereits im Zeitpunkt der Löschung der nationalen Marke vorgelegen haben.','Bei Nichtbenutzungsverfall ist rückblickend auf das Erlöschen der nationalen Marke abzustellen. Für einen Verzicht hat der BGH klargestellt, dass die wirksame Verzichtserklärung entscheidet und nicht erst die spätere Eintragung der Löschung im Register. Ein zusätzlicher Nachweis fortdauernden Verfalls bis zum Tag der Feststellungsentscheidung ist nicht erforderlich; die 2026 erfolgte Streichung von „auch schon“ in Absatz 2 Satz 2 beseitigt gerade den früheren missverständlichen Zusatz.').replace('Der heutige Registerstatus „gelöscht“ erledigt die Frage daher nicht.','Der heutige Registerstatus „gelöscht“ erledigt die Frage daher nicht. Eine erst nach dem Erlöschen wieder aufgenommene Zeichenverwendung lässt die aufgegebene nationale Marke auch nicht wieder entstehen und heilt ihren damaligen Nichtbenutzungszustand nicht.').replace('Entscheidend ist, ob der aufgegebene nationale Bestand den fortwirkend beanspruchten Rang wirklich tragen konnte.','Entscheidend ist, ob der aufgegebene nationale Bestand den fortwirkend beanspruchten Rang wirklich tragen konnte. Gegenstand der Feststellung ist die frühere deutsche Marke; die Vorschrift erklärt nicht unmittelbar die Unionsmarke insgesamt für nichtig. Absatz 1 Satz 2 nimmt vielmehr dem beanspruchten nationalen Zeitrang seine Wirkung.\n\nDer vollständig gelesene BGH-Fall [PUC II](cases/bgh-puc-ii.md), Urteil vom 8. November 2018, I ZR 126/15, Rn. 24 und 50–59, belegt diese zeitlichen Unterscheidungen. Er erging zu § 125c alter Fassung, dem heutigen § 120. Seine damaligen Aussagen zur Beweislast werden hier nicht als heutige allgemeine Beweislastregel übernommen; auch die ältere Artikelnummerierung der Unionsverordnung bleibt historisch.')
revisions['p121']=base['p121'].replace('Die Umwandlung einer Unionsmarke in eine deutsche Position wird nach Übermittlung des Antrags kostenrechtlich und verfahrensmäßig eingeordnet.','Die Umwandlung einer Unionsmarke in eine deutsche Position wird nach Übermittlung des Antrags durch das Unionsamt kostenrechtlich und verfahrensmäßig eingeordnet. Der bloße Entschluss zur nationalen Fortsetzung oder ein formloses Schreiben an das DPMA ersetzt den in Absatz 1 bezeichneten Übermittlungsweg nicht.').replace('Absatz 2 behandelt eine noch nicht eingetragene Unionsmarke wie eine nationale Anmeldung, erhält aber Anmelde-, Prioritäts- oder gegebenenfalls beanspruchten nationalen Zeitrang.','Absatz 2 behandelt eine noch nicht eingetragene Unionsmarke wie eine nationale Anmeldung, erhält aber den unionsrechtlichen Anmelde- oder Prioritätstag. War für ihre Anmeldung die Seniorität einer deutschen Registermarke nach Artikel 39 beansprucht, tritt dieser nationale Zeitrang an die Stelle des sonst maßgeblichen Tages. Die Herkunft des einzelnen Datums muss deshalb aus den Anmeldeunterlagen ersichtlich bleiben.').replace('Gegen die Eintragung kann Widerspruch nicht erhoben werden.','Gegen die Eintragung kann Widerspruch nicht erhoben werden.')
revisions['p122']=base['p122'].replace('Absatz 5 übernimmt die bezeichneten Regeln zu bestimmten Kosten und zur Streitwertbegünstigung.','Absatz 5 übernimmt § 140 Absatz 4 zu Patentanwaltskosten und § 142 zur Streitwertbegünstigung. Die Kostenverweisung ist im Licht der Rechtsprechung zur notwendigen patentanwaltlichen Mitwirkung auszulegen; die bloße Mitwirkung führt nicht automatisch zu vollständiger Erstattung. Eine Streitwertbegünstigung setzt ihrerseits den Antrag und die wirtschaftlichen Voraussetzungen des § 142 voraus.').replace('Zur notwendigen patentanwaltlichen Mitwirkung und zur heutigen Verweisungsstruktur siehe die [Fallkarte „Kosten des Patentanwalts VII“](cases/bgh-patentanwaltskosten.md).','Der erneut vollständig gelesene BGH-Beschluss vom 13. Oktober 2022, I ZB 59/19, Rn. 9–12 und 19–28, verlangt die Prüfung der Notwendigkeit; er verweist mangels hierzu getroffener Feststellungen zurück. Zur historischen und heutigen Verweisungsstruktur siehe die [Fallkarte „Kosten des Patentanwalts VII“](cases/bgh-patentanwaltskosten.md).')
revisions['p126']=base['p126']+'\n\nBGH, Urteil vom 31. März 2016, I ZR 86/13 – [Himalaya Salz](cases/bgh-himalaya-salz.md), Rn. 10–18, ordnet den Schutz der §§ 126 ff. als kennzeichenrechtlichen Schutz ein. Das Urteil belegt keine pauschale Qualitätsgarantie jedes geografischen Namens. Die dortige Trennung einfacher Herkunftsangaben von qualitätsgebundenen Unionsbezeichnungen ist wegen des seither geänderten Unionsrechts und der neuen Absätze 5 und 6 des § 127 mit der heutigen Systemabgrenzung zusammenzulesen.'
revisions['p127']=base['p127'].replace('Absatz 6 nimmt bestimmte noch laufende Unionsanträge von dieser Bereichsausnahme aus.','Absatz 6 nimmt bestimmte noch laufende Unionsanträge von dieser Bereichsausnahme aus: Maßgeblich ist bei Agrarangaben die Einreichung bei der Kommission, bei handwerklichen oder industriellen Angaben die Einreichung beim EUIPO. Ein nur beim DPMA anhängiger Antrag genügt dafür nach diesem Wortlaut nicht. Die Ausnahme dauert nur bis zur Entscheidung oder sonstigen Beendigung des Eintragungsverfahrens; sie macht Qualitäts- und Rufvoraussetzungen nicht entbehrlich. Ergänzend stellt § 158 Absatz 11 die dort geregelte Unterrichtung nach Artikel 70 Absatz 2 der Einreichung gleich.').replace('Das nationale Regime und der registrierungsbezogene Unionsschutz dürfen nicht vermischt werden.','Das nationale Regime und der registrierungsbezogene Unionsschutz dürfen nicht vermischt werden.\n\nDie Herkunftstäuschung ist aus der konkreten Gesamtpräsentation zu ermitteln. Im vollständig gelesenen Fall [Himalaya Salz](cases/bgh-himalaya-salz.md), BGH I ZR 86/13 vom 31. März 2016, Rn. 19–34, beseitigte ein entfernter oder widersprüchlicher Hinweis im Fließtext die irreführende Angebotsüberschrift nicht. Selbst eine wissenschaftlich möglicherweise richtige Gebietszuordnung entschied nicht allein über das Verkehrsverständnis; der BGH berücksichtigte die mögliche Klarstellung und die betroffenen Interessen. Er ließ mehrere allgemeine Fragen zu einer strengeren Irreführungsquote und zur eigenständigen Relevanzanforderung ausdrücklich offen. Der Fall ersetzt deshalb weder die heutige Bereichsabgrenzung nach Absatz 5 noch die Prüfung eines konkreten Schutzstatus.')
revisions['p128']=base['p128'].replace('Absatz 1 vermittelt Unterlassung bei Wiederholungs- oder drohender Verletzungsgefahr und bestimmt die Anspruchsberechtigten durch Verweisung auf das Wettbewerbsrecht.','Absatz 1 vermittelt Unterlassung bei Wiederholungsgefahr und bereits bei drohender Zuwiderhandlung. Ein Verschulden verlangt dieser Absatz nicht. Die Berechtigung folgt aus § 8 Absatz 3 UWG: Die dort beschriebenen Mitbewerber, qualifizierten Verbände und Einrichtungen sowie berufsständischen Stellen sind jeweils nach ihren eigenen Voraussetzungen zu prüfen. Nicht jeder beliebige Verbraucher oder jede Erzeugergruppe ist schon kraft Interesses klagebefugt.').replace('Er überträgt zugleich die bezeichneten Beseitigungs- und Informationsinstrumente.','Entsprechend gelten § 18 für Vernichtung und Rückruf, § 19 für Auskunft, § 19a für Vorlage und Besichtigung und § 19c für Urteilsbekanntmachung. Diese Verweisung enthält jeweils mehr als eine allgemeine Befugnis zur Beseitigung; insbesondere bleiben die Grenzen der einzelnen Maßnahme zu beachten.').replace('Auch die Voraussetzungen des § 127 müssen vollständig vorliegen.','Der Nutzer muss seinen eigenen ersatzfähigen Schaden und dessen Verursachung darlegen; die Berücksichtigung des Verletzergewinns bedeutet keine voraussetzungslose Herausgabe jedes Umsatzes. Auch die Voraussetzungen des § 127 müssen vollständig vorliegen.').replace('Ein Verstoß gegen irgendeine regionale Werbeerwartung ist nicht allein durch § 128 bereits als Verletzung festgestellt.','Ein Verstoß gegen irgendeine regionale Werbeerwartung ist nicht allein durch § 128 bereits als Verletzung festgestellt.\n\nBGH I ZR 86/13 – [Himalaya Salz](cases/bgh-himalaya-salz.md), Rn. 13 und 36–39, unterscheidet den berechtigten Nutzer beim Schadensersatz von der wettbewerbsrechtlich bestimmten Unterlassungsberechtigung. Für Unternehmensmitarbeiter und Beauftragte besteht die gesetzliche Verweisung auf § 14 Absatz 7. Im konkreten Fall haftete die Onlinehändlerin aber bereits als Täterin ihres eigenen Verkaufsangebots; die vom Lieferanten eingespielten Angaben entlasteten sie nicht. Das ist keine Aussage, dass jede Plattform für beliebige fremde Angebote identisch haftet.')
revisions['p129']=base['p129']+'\n\nPraktische Checkliste zum Ende des Abschnitts: Herkunftsaussage und etwaige Gattungsbedeutung anhand des Verkehrs bestimmen; tatsächliche Herkunft und gegebenenfalls Qualität oder Ruf belegen; Produktbereich und Unionsverfahrensstand einschließlich § 158 Absatz 11 feststellen; Unterlassungsberechtigung von Nutzerschaden trennen; Anspruchsart, Lieferdatum und Kenntnis für die Verjährung gesondert erfassen. Die Verweisung auf § 20 bezieht auch dessen Restanspruchsregel unter Verweis auf § 852 BGB ein. Ein abgelaufener Schadensersatzanspruch darf daher nicht ohne Prüfung mit dem Wegfall sämtlicher vermögensrechtlichen Folgen gleichgesetzt werden.'
revisions['p130']=base['p130'].replace('Absätze 1 und 2 weisen die nationale Prüfung geografischer Anträge dem Amt und dort den Markenabteilungen zu.','Absätze 1 und 2 weisen die nationale Prüfung geografischer Anträge dem DPMA und dort den Markenabteilungen zu. Die Einreichungsverweisung auf § 32 Absatz 1 betrifft das Amt und gegebenenfalls ein zur Entgegennahme bestimmtes Patentinformationszentrum; sie übernimmt nicht sämtliche Form- und Inhaltsanforderungen einer Individualmarke aus § 32 Absatz 2.').replace('Absatz 6 macht wesentliche Verfahrensdaten online zugänglich, Absatz 7 ist weggefallen.','Absatz 6 verlangt Onlinezugang zu Name, Eingang, Veröffentlichungen, Einspruchsfrist, Weiterleitung und Unionsregisternummer. Dazu kommen die Mitteilungen an das EUIPO über Anfechtung und rechtskräftige Ungültigerklärung der nationalen positiven Entscheidung sowie öffentliche Verhandlungstermine nach § 67 Absatz 2. So wird auch ein streitiger oder aufgehobener Verfahrensstand sichtbar. Absatz 7 ist ausdrücklich weggefallen; eine ältere zusätzliche Prüfungsregel lässt sich daraus nicht fortführen.')
revisions['p131']=base['p131'].replace('Absatz 1 ermöglicht dessen Aufforderung zu zusätzlichen Informationen nach einem Verlangen des Unionsamts.','Absatz 1 ermöglicht dessen Aufforderung zu zusätzlichen Informationen nach einem Verlangen des Unionsamts. Das „kann“ betrifft diese nationale Aufforderung; erhaltene entsprechende Informationen muss das DPMA unverzüglich weiterleiten.').replace('Absatz 2 betrifft förmliche Vervollständigung oder Berichtigung auf entsprechendes Ersuchen und verlangt eine angemessene Frist sowie unverzügliche Weiterleitung.','Absatz 2 verlangt demgegenüber auf das bezeichnete Ersuchen die Aufforderung zur Vervollständigung oder Berichtigung, verbunden mit einer angemessenen Frist und unverzüglicher Weiterleitung. Für diese Mängelbehebung setzt die Norm keine pauschale Zwei-Monats-Frist wie für den Einspruch nach § 130 Absatz 4; die konkret gesetzte Frist ist gesondert festzuhalten.')
revisions['p132']=base['p132'].replace('das deutsche Amt reicht den Antrag aber gerade nicht beim Unionsamt ein.','das deutsche Amt reicht den Antrag aber gerade nicht beim Unionsamt ein. Aus dieser Ausnahme folgt keine allgemeine Befreiung von den Veröffentlichungs- und Prüfanforderungen der entsprechend anwendbaren Regeln. Auch darf das Fehlen einer Antragseinreichung beim EUIPO nicht mit dem Ausschluss jeder unionsrechtlich vorgesehenen Information gleichgesetzt werden.').replace('Absatz 4 schützt den ursprünglichen Antragsteller durch Gelegenheit zur Stellungnahme und Zustellung der Beschlüsse.','Absatz 4 schützt denjenigen Antragsteller, in dessen Namen die betroffene Angabe eingetragen wurde: Ihm ist Gelegenheit zur Stellungnahme zu geben und sind Beschlüsse zuzustellen. Das gilt auch, wenn ein anderer eine Änderung oder Löschung betreibt; die bloße Beteiligung dieses neuen Antragstellers ersetzt die Anhörung des bezeichneten früheren Antragstellers nicht.')
revisions['p133']=base['p133'].replace('Absatz 1 eröffnet Beschwerde zum Bundespatentgericht und Rechtsbeschwerde zum Bundesgerichtshof unter entsprechender Anwendung der jeweiligen Verfahrensabschnitte.','Absatz 1 eröffnet Beschwerde zum Bundespatentgericht und Rechtsbeschwerde zum Bundesgerichtshof unter entsprechender Anwendung der jeweiligen Verfahrensabschnitte. Die Rechtsbeschwerde ist damit nicht gegen jede Entscheidung frei eröffnet; die Zulässigkeitsvoraussetzungen insbesondere des § 83 bleiben zu prüfen.').replace('Für nicht zugestellte Beschlüsse gilt eine besondere Zweimonatsfrist nach Veröffentlichung.','Personen, denen der Beschluss nicht zugestellt wurde, müssen binnen zwei Monaten nach Veröffentlichung Beschwerde einlegen. Die Sonderregel stellt auf die fehlende Zustellung an die betroffene Person ab; für zugestellte Beschlüsse bleibt grundsätzlich die Monatsfrist des entsprechend anwendbaren § 66 Absatz 2 zu beachten.').replace('Nach einer weiteren Beschwerde ist dieser Rücklauf ausgeschlossen.','Gegen den nach diesem Rücklauf ergehenden neuen Beschluss bleibt eine erneute Beschwerde möglich; nur eine abermalige Behandlung als Einspruch nach Satz 1 ist ausgeschlossen. Es handelt sich mithin nicht um einen Ausschluss gerichtlichen Rechtsschutzes nach der zweiten Behördenentscheidung.')
revisions['p134']=base['p134'].replace('Absatz 2 nennt erforderliche Befugnisse während der Geschäfts- oder Betriebszeit: Betreten und Besichtigen, Stichproben, verdeckte Erwerbe, Unterlageneinsicht und Auskunft; erfasst sind auch öffentliche Verkaufsorte und elektronischer Handel.','Absatz 2 nennt erforderliche Befugnisse während der Geschäfts- oder Betriebszeit: Betreten und Besichtigen von Geschäftsräumen, Grundstücken, Verkaufseinrichtungen und Transportmitteln, Entnahme von Stichproben gegen Empfangsbescheinigung, verdeckte Erwerbe, Unterlageneinsicht und Auskunft. Erfasst sind die bezeichneten Hersteller, Inverkehrbringer und grenzüberschreitenden Wirtschaftsbeteiligten; die Befugnisse reichen auch auf öffentliche Verkaufsorte und elektronischen Handel.').replace('Absatz 3 regelt Rückgabe, Härteausgleich bei Proben und Unterrichtung nach verdecktem Kauf einschließlich möglichem Ersatz von Kaufpreis und Versand.','Absatz 3 verlangt nach der Prüfung die Rückgabe sowohl entnommener als auch verdeckt erworbener Erzeugnisse. Für entnommene Proben gibt es Entschädigung bis zum Verkaufspreis nur zur Vermeidung einer unbilligen Härte. Nach verdecktem Erwerb muss die Behörde den Verkäufer nach Erhalt der Ware über den Erwerb als Kontrollbehörde unterrichten; sie kann ihrerseits vom Verkäufer Kaufpreis und Versandkosten zurückverlangen, sofern dadurch keine unbillige Härte entsteht. Zahlungsrichtung und Härtefallprüfung unterscheiden sich somit in den beiden Kontrollformen.').replace('Absatz 4 konkretisiert die Mitwirkung von Inhabern und Betriebsleitern,','Absatz 4 konkretisiert die Mitwirkung von Inhabern und Betriebsleitern: Zutritt und Besichtigung gestatten, Ware zur Besichtigung darlegen, erforderliche Hilfe leisten, Probenentnahme zulassen, Geschäftsunterlagen vorlegen und prüfen lassen sowie Auskunft geben.').replace('Absatz 5 erweitert','Absatz 5 erweitert').replace('Absatz 6 schützt vor selbst- oder angehörigenbelastender Auskunft.','Absatz 6 schützt bei konkreter Gefahr strafrechtlicher oder bußgeldrechtlicher Verfolgung vor selbst- oder angehörigenbelastender Auskunft unter Verweis auf § 383 Absatz 1 Nummer 1 bis 3 ZPO. Das betrifft die entsprechende Frage und ist kein pauschales Recht, jede Besichtigung oder Dokumentenprüfung zu verhindern.').replace('Vertriebsbeschränkungen und Sicherstellung;','auch vorläufige Verbote oder Beschränkungen des Inverkehrbringens oder Handelns mit widerrechtlich gekennzeichneten Erzeugnissen oder Werbematerial sowie auch vorläufige Sicherstellung der Erzeugnisse;')
# Ensure ordinary edits touch only the assigned block; keep every other byte of prose.
assert len(revisions)==14
for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 def f(m):
  ident=m[1]
  if ident not in revisions:return m[0]
  assert m[2].strip()==base[ident]
  return '=== '+ident+'\n'+revisions[ident].strip()+'\n\n'
 out=re.sub(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',f,s,flags=re.M|re.S)
 if out!=s:p.write_text(out)
print('Revised',len(revisions),'assigned blocks; six retained after review')
